class METDebugShipConfirm extends RunBase
{
    DialogField shipmentIdField;
    MetShipmentId shipmentId;


}

Method.Source:
public Object dialog()
{
    Dialog dialog = super();

    dialog.caption("Select shipment to finalise");
    shipmentIdField = dialog.addField(extendedTypeStr(MetShipmentId));
    return dialog;
}

public boolean getFromDialog()
{
    shipmentId = shipmentIdField.value();
    return super();
}

public void run()
{
    if (shipmentId)
    {
        ttsbegin;
        METOrderShipmentConfirmation shipmentConfirmation = METOrderShipmentConfirmation::construct(shipmentId);
        shipmentConfirmation.run();
        ttscommit;
    }
}

/// <summary>
/// Class entry point. The system will call this method when a designated menu
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    METDebugShipConfirm debugShipConfirm = new METDebugShipConfirm();

    if (debugShipConfirm.prompt())
    {
        debugShipConfirm.run();
    }
}
